function relMeEdit(cid){const c=getC(cid);if(!c)return;openModal(`<h3>你和${esc(c.remark||c.name)}的关系</h3><div class="hint">这里改的就是TA资料里的「关系」，只存一份，聊天里TA就按这个认你。</div><div class="field"><input id="relme_in" maxlength="20" value="${esc(c.relation||'')}" placeholder="例如：妻子 / 女朋友 / 未婚妻"></div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="relMeSave('${cid}')">保存</button></div>`);}
function relMeSave(cid){const c=getC(cid),i=$('#relme_in');if(!c||!i)return;c.relation=String(i.value||'').trim().slice(0,20);save();closeModal();render();toast('已保存');}
function relCapSet(v){const r=relInit();r.detailCap=Math.max(1,Math.min(10,Math.round(+v||6)));save();const t=$('#relcap_t');if(t)t.textContent=r.detailCap+' 个';}
