async function relEditDelete(){const e=_relEdit;if(!e||!e.id)return;if(!await uiConfirm('删除「'+relName(e.a)+'」和「'+relName(e.b)+'」的关系？',{danger:true}))return;const r=relInit();const old=r.links.find(x=>x.id===e.id);if(old)relFamilyBlockLink(old);r.links=r.links.filter(x=>x.id!==e.id);save();_relEdit=null;back();toast('已删除');}
let _relPersonDraft=null;
