/* CONTACT_PHOTO_DEL_V1（2026-10-18 她发现朋友资料里的照片删不掉）：每张右上角一个 ✕，确认后删掉这一张 */
async function contactPhotoDel(id,i){const c=getC(id);if(!c||!Array.isArray(c.profilePhotos)||!c.profilePhotos[i])return;if(!await uiConfirm('删除这张照片？',{danger:true,yes:'删除'}))return;c.profilePhotos.splice(i,1);save();contactPhotosOpen(id);render();toast('已删除');}
