function roleImageStudioThumb(src,label){src=String(src||'');const ready=isStoredImgRef(src)?(_imgCache[src.slice(4)]||''):src;return ready?`<img src="${ready}" alt="${esc(label||'参考图')}" style="width:72px;height:92px;object-fit:cover;border-radius:10px">`:`<span style="width:72px;height:92px;border-radius:10px;background:#242428;display:grid;place-items:center;color:#777;font-size:12px">图片加载中</span>`;}
function roleImageStudioWardrobeThumb(src,label){src=String(src||'');const ready=isStoredImgRef(src)?(_imgCache[src.slice(4)]||''):src;return ready?`<img src="${ready}" alt="${esc(label||'衣物参考')}" loading="lazy" decoding="async" style="display:block;width:100%;aspect-ratio:4/5;object-fit:cover;background:#242428">`:`<span style="width:100%;aspect-ratio:4/5;background:#242428;display:grid;place-items:center;color:#777;font-size:12px">图片加载中</span>`;}
