async function roleImageStudioDescribe(src,kind){try{return await visionAPI(src,kind==='face'?'只描述图中主要成年人物可稳定复用的身份外观：脸型、发际线、发型和梳理方向、发色、眉眼、鼻唇、肤色、年龄感、体型及明显辨识特征。不要描述背景、动作和衣服，不猜身份，不评价好看与否。':'只描述这件衣物或配饰可用于图像生成的视觉特征：准确类别、主辅颜色、版型剪裁、领口袖型、长度、面料质感、图案、配件和穿着轮廓。不要描述人物脸和背景。',{primaryOnly:false});}catch(_){return'';}}
