function roleImageStudioFaceActions(id,rid){const c=roleImageStudioOwner(id),st=roleImageStudioCapture(id),row=st&&st.identityRefs.find(x=>x.id===rid);if(!c||!row)return;openModal(`<h3>${roleImageStudioFaceLabel(row.angle)}</h3><div style="max-width:220px;margin:8px auto 12px">${roleImageStudioWardrobeThumb(row.image,roleImageStudioFaceLabel(row.angle))}</div><div class="hint">这张图片会作为固定人物身份参考，识别长文已收起，不会再占满工作室页面。</div>${row.note?`<details style="margin:12px 0"><summary style="cursor:pointer;color:#d0aa79">查看识别详情</summary><div style="margin-top:8px;padding:10px;border-radius:10px;background:#19191c;color:#aaa;line-height:1.55;max-height:180px;overflow:auto">${esc(row.note)}</div></details>`:''}<div class="btns"><button class="btn g" onclick="closeModal()">完成</button><button class="btn r" onclick="closeModal();roleImageStudioFaceDelete('${id}','${rid}')">删除参考</button></div>`);}
