function roleImageStudioOutfitReplaceImage(id){const draft=_roleImageOutfitDraft;if(!draft||!draft.edit||draft.roleId!==id)return;const name=$('#rio_name'),occasion=$('#rio_occasion'),note=$('#rio_note'),timing=roleImageStudioOutfitReadTimeRange();if(name)draft.name=name.value;if(occasion)draft.occasion=occasion.value;if(note)draft.note=note.value;draft.timeStart=timing.enabled?timing.start:'';draft.timeEnd=timing.enabled?timing.end:'';pickFile('image/*',async f=>{if(_roleImageOutfitDraft!==draft)return;const c=roleImageStudioOwner(id),st=roleImageStudio(c,true),row=st&&st.outfits.find(x=>x.id===draft.id);if(!c||!row)return;aiLoad('正在替换衣物图片…');try{const src=await compress(f,1200,.84);try{await primeImageForSave(src);}catch(_){}if(!roleImageStudioOutfitApplyImage(row,src))return;draft.image=src;save(0);roleImageStudioOutfitModal(id,draft,'编辑角色衣物');toast('只替换了衣物图片，文字和时间设置保持不变');}finally{aiDone();}});}
function roleImageStudioOutfitActions(id,rid){const c=roleImageStudioOwner(id),st=roleImageStudioCapture(id),row=st&&st.outfits.find(x=>x.id===rid);if(!c||!row)return;const fixed=roleImageTimeRangeLabel(row);openModal(`<h3>${esc(row.name)}</h3><div style="display:flex;justify-content:center;margin:8px 0 12px">${roleImageStudioThumb(row.image,row.name)}</div><div class="hint" style="text-align:center;margin-bottom:12px">${esc(roleImageOccasionLabel(row.occasion))}${fixed?' · '+esc(fixed):' · 未固定时间'}${row.enabled===false?' · 已停用':''}</div><button class="btn p" onclick="closeModal();roleImageStudioOutfitEdit('${id}','${rid}')">编辑名称、场景、时间和详细描述</button><button class="btn g" style="margin-top:8px" onclick="closeModal();roleImageStudioOutfitToggle('${id}','${rid}')">${row.enabled!==false?'暂停参与随机':'恢复参与随机'}</button><button class="btn g" style="margin-top:8px;color:#ff6b6b" onclick="closeModal();roleImageStudioOutfitDelete('${id}','${rid}')">删除这件衣物</button><button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
async function roleImageStudioOutfitTimeSave(id){const c=roleImageStudioOwner(id),st=roleImageStudio(c,true),draft=_roleImageOutfitDraft;if(!c||!st||!draft||draft.roleId!==id)return;const timing=roleImageStudioOutfitReadTimeRange(),err=roleImageStudioOutfitTimeError(timing);if(err){toast(err);return;}const next={start:timing.enabled?timing.start:'',end:timing.enabled?timing.end:''};draft.timeStart=next.start;draft.timeEnd=next.end;const row=st.outfits.find(x=>x.id===draft.id);if(!row){toast('时间段已暂存，点“保存到衣柜”后正式生效');return;}const prev={start:row.timeStart||'',end:row.timeEnd||''};row.timeStart=next.start;row.timeEnd=next.end;let ok=false;try{ok=await saveNowAsync();}catch(_){}if(!ok){row.timeStart=prev.start;row.timeEnd=prev.end;toast('时间没有写入本机，请检查存储权限后重试');return;}toast(timing.enabled?'这套衣服的时间段已单独保存':'已取消固定时间，恢复随机选择');}
async function roleImageStudioOutfitSave(id){const c=roleImageStudioOwner(id),st=roleImageStudio(c,true),draft=_roleImageOutfitDraft;if(!c||!st||!draft||draft.roleId!==id)return;if(draft._saving){toast('正在保存这件衣物，请稍等');return;}const name=($('#rio_name')&&$('#rio_name').value.trim())||'未命名衣物',occasion=($('#rio_occasion')&&$('#rio_occasion').value)||'daily',timing=roleImageStudioOutfitReadTimeRange(),manual=($('#rio_note')&&$('#rio_note').value.trim())||'',err=roleImageStudioOutfitTimeError(timing);if(err){toast(err);return;}const timeStart=timing.enabled?timing.start:'',timeEnd=timing.enabled?timing.end:'';draft._saving=true;if(draft.edit){const row=st.outfits.find(x=>x.id===draft.id);if(!row){draft._saving=false;toast('这件衣物已经不存在');return;}const prev={name:row.name,occasion:row.occasion,timeStart:row.timeStart,timeEnd:row.timeEnd,note:row.note};row.name=name;row.occasion=occasion;row.timeStart=timeStart;row.timeEnd=timeEnd;row.note=manual.slice(0,800);let ok=false;try{ok=await saveNowAsync();}catch(_){}if(!ok){Object.assign(row,prev);draft._saving=false;toast('衣物设置没有写入本机，请检查存储权限后重试');return;}draft._saving=false;_roleImageOutfitDraft=null;closeModal();render();toast('衣物信息和固定时间已保存');return;}aiLoad('正在识别衣物版型和材质…');try{try{await primeImageForSave(draft.image);}catch(_){}if(roleImageStudioOwner(id)!==c||_roleImageOutfitDraft!==draft)return;const auto=await roleImageStudioDescribe(draft.image,'outfit'),note=[manual,auto].filter(Boolean).join('；').slice(0,800);if(roleImageStudioOwner(id)!==c||_roleImageOutfitDraft!==draft)return;const previous=st.outfits.slice();st.outfits=st.outfits.filter(x=>x.id!==draft.id);st.outfits.unshift({id:draft.id,name,occasion,image:draft.image,note,enabled:draft.enabled!==false,timeStart,timeEnd});let ok=false;try{ok=await saveNowAsync();}catch(_){}if(!ok){st.outfits=previous;toast('新衣物没有写入本机，请检查存储权限后重试');return;}draft._saving=false;_roleImageOutfitDraft=null;closeModal();render();toast('已加入衣柜');}finally{draft._saving=false;aiDone();}}
