async function roleImageStudioTest(id){const photoAccount=actId(),c=roleImageStudioOwner(id),st=roleImageStudioCapture(id),el=$('#ris_test');if(!c||!st)return;if(!st.enabled){toast('请先开启“使用自定义'+(c._userImageStudio?'本人':'角色')+'形象”');return;}if(!S.settings.imgGen||!imageGenerationAvailable()){toast('请先在 AI 账户开启并配置图片生成');return;}const scene=(el&&el.value.trim())||(c._userImageStudio?'本人在日常环境里随手拍一张自然半身照':'当前角色在日常环境里随手拍一张自然半身照'),objectOnly=roleImageStudioTestObjectOnly(scene);save();const prompt=roleImageStudioPrompt(c,{scene,requestText:scene,objectOnly,userRequest:scene});aiLoad('正在按固定形象和衣柜生成测试图…');try{const url=await genImage(prompt,{roleId:id,accountId:photoAccount}),src=await stableImageSrc(url);if(roleImageStudioOwner(id)!==c)return;openModal(`<h3>形象测试预览</h3><div class="hint">这张图没有发送到聊天。场景识别：${esc(roleImageOccasionLabel(roleImageOccasion(scene)))}${objectOnly?' / 纯场景':c._userImageStudio?' / 用户本人':' / 角色本人'}</div><img src="${src}" alt="形象测试预览" style="display:block;width:100%;max-height:62vh;object-fit:contain;border-radius:12px;margin:12px 0"><button class="btn g" onclick="closeModal()">关闭预览</button>`);}catch(e){toast('测试生成失败：'+String(e&&e.message||'图片接口没有返回结果').slice(0,100),7000);}finally{aiDone();}}
