function roleMomentCard(c,p,pinned){const tx=cleanMomentText(p.text)||'',img=(p.images||[])[0]||'',imgSrc=storedImageElementSource(img),d=roleMomentDateParts(p.time);return `<button class="wx-role-moment-card ${pinned?'pinned':''} ${img?'has-image':'no-image'}" onclick="roleMomentDetail('${c.id}','${p.id}')"><time>${pinned?'<b>置顶</b>':`<b>${String(d.day).padStart(2,'0')}</b><small>${d.month}月</small>`}</time><span class="moment-main"><span class="copy"><small>${esc(tx||'分享了照片')}</small><i>${d.year}年${d.month}月${d.day}日 ${d.time}</i></span>${imgSrc?`<img src="${imgSrc}" alt="动态配图">`:''}</span><em>›</em></button>`;}
