function editRoleNetizenReplyStyle(id){const c=getC(id);if(!c)return;const current=String(c.xNetizenReplyStyle||'');openModal(`<h3>回复网友的风格</h3><div class="hint">只用于 ${esc(c.remark||c.name)} 在 X 公开回复普通网友。无论怎么自定义，网友都不会被当成你，也不会带入微信私聊、共同记忆或亲密管束方式。</div><div style="display:flex;gap:6px;flex-wrap:wrap;margin:10px 0">${[['礼貌有距离','礼貌、简短、有分寸，与陌生网友保持明显距离。'],['冷淡简短','冷淡克制，能一句说完就不说两句，不主动延伸关系。'],['幽默随和','轻松幽默但不过度熟络，不暧昧，也不冒犯。'],['犀利克制','观点直接、可以反驳，但不辱骂、不攻击网友本人。']].map(x=>`<button class="minibtn" onclick="var e=$('#role_net_reply_style');if(e)e.value=${jq(x[1])}">${x[0]}</button>`).join('')}</div><div class="field"><textarea id="role_net_reply_style" rows="5" maxlength="500" placeholder="留空时按角色性格自然、礼貌并保持距离">${esc(current)}</textarea></div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="saveRoleNetizenReplyStyle('${id}')">保存</button></div>`);}
function saveRoleNetizenReplyStyle(id){const c=getC(id),el=$('#role_net_reply_style');if(!c||!el)return;const v=String(el.value||'').trim().slice(0,500);if(v)c.xNetizenReplyStyle=v;else delete c.xNetizenReplyStyle;save();closeModal();render();toast(v?'网友回复风格已保存':'已恢复默认的公开回复风格');}
